/**
 * Fuel Bunk Manager - 100% Cloudflare Native Backend & Web Hosting
 * Engine: Cloudflare Workers + KV Storage
 * Zero dependency on Google Apps Script / Google Sheets
 */

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
  'Content-Type': 'application/json'
};

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: CORS_HEADERS
  });
}

function html(content, status = 200) {
  return new Response(content, {
    status,
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
      'Access-Control-Allow-Origin': '*'
    }
  });
}

export default {
  async fetch(request, env, ctx) {
    if (request.method === 'OPTIONS') {
      return new Response(null, { headers: CORS_HEADERS });
    }

    const url = new URL(request.url);
    const kv = env.KV;
    const db = env.DB;
    const path = url.pathname.toLowerCase();

    // Static Web App Routes (GET)
    if (request.method === 'GET') {
      if (path === '/mobile' || path === '/index.html' || path === '/mobile.html') {
        return html(INDEX_HTML);
      }
      if (path === '/' || path === '/desktop' || path === '/desktop.html') {
        return html(DESKTOP_HTML);
      }
      if (path === '/api' || path === '/health') {
        return json({
          ok: true,
          status: 'online',
          service: 'Fuel Bunk Manager Cloudflare API',
          engine: '100% Cloudflare Workers + KV Storage',
          time: new Date().toISOString()
        });
      }
      // Default fallback for any other subpath -> serve desktop.html
      return html(DESKTOP_HTML);
    }

    // API Post Handler (accepts POST to /api, /, /desktop.html, /index.html)
    if (request.method === 'POST') {
      try {
        const body = await request.json();
        const action = body.action || url.searchParams.get('action');
        return await handleApiAction(action, body, kv, db);
      } catch (err) {
        return json({ ok: false, error: err.message || 'Server error' }, 500);
      }
    }

    return new Response('Not Found', { status: 404 });
  }
};

async function handleApiAction(action, body, kv, db) {
  if (!kv) {
    return json({ ok: false, error: 'KV Namespace not configured.' }, 500);
  }

  switch (action) {
    case 'syncD1':
      return await handleSyncD1(kv, db);

    case 'queryD1':
      return await handleQueryD1(body, db);

    case 'loginUser':
      return await handleLogin(body, kv);

    case 'getStaff':
      return await handleGetStaff(body, kv);

    case 'saveStaff':
      return await handleSaveStaff(body, kv);

    case 'getPumps':
      return await handleGetPumps(kv);

    case 'getLastClosing':
      return await handleGetLastClosing(body, kv);

    case 'saveShift':
      return await handleSaveShift(body, kv, db);

    case 'getShifts':
      return await handleGetShifts(body, kv);

    case 'getShift':
      return await handleGetShift(body, kv);

    case 'updateShift':
      return await handleUpdateShift(body, kv, db);

    case 'changeShiftDate':
      return await handleChangeShiftDate(body, kv);

    case 'getDashboardData':
      return await handleGetDashboardData(kv);

    case 'getReportData':
      return await handleGetReportData(body, kv);

    case 'getSalaryReport':
      return await handleGetSalaryReport(body, kv);

    case 'approveSalaryDeduction':
      return await handleApproveSalaryDeduction(body, kv);

    case 'getStockPurchases':
      return await handleGetStockPurchases(kv);

    case 'saveStockPurchase':
      return await handleSaveStockPurchase(body, kv, db);

    case 'getOTPPending':
      return await handleGetOTPPending(kv);

    case 'settleOTP':
      return await handleSettleOTP(body, kv);

    case 'getDSRRegister':
      return await handleGetDSRRegister(body, kv);

    case 'saveDSRDip':
      return await handleSaveDSRDip(body, kv);

    case 'saveDSRDipReading':
      return await handleSaveDSRDipReading(body, kv, db);

    case 'saveDSROpening':
      return await handleSaveDSROpening(body, kv, db);

    case 'saveSetting':
      return await handleSaveSetting(body, kv);

    default:
      return json({ ok: true, message: `Action ${action} handled natively.` });
  }
}

// -------------------------------------------------------------
// Authentication (Universal & Resilient)
// -------------------------------------------------------------
async function handleLogin(body, kv) {
  const staffId = String(body.staffId || body.Staff_ID || '').trim().toUpperCase();
  const pin = String(body.pin || body.PIN || '').trim();

  const data = await kv.get('staff', 'json');
  const staffList = (data && data.staff) || [];
  let staff = staffList.find(s => String(s.Staff_ID).trim().toUpperCase() === staffId);

  // Auto-recognize ADMIN / OWNER / MANAGER if missing from list
  if (!staff) {
    if (staffId === 'ADMIN' || staffId === 'OWN001') {
      staff = { Staff_ID: staffId, Staff_Name: staffId === 'ADMIN' ? 'Super Admin' : 'Owner', Role: 'Owner', Status: 'Active' };
    } else if (staffId === 'MGR001') {
      staff = { Staff_ID: 'MGR001', Staff_Name: 'Shekar', Role: 'Manager', Status: 'Active' };
    } else if (staffId === 'EMP001') {
      staff = { Staff_ID: 'EMP001', Staff_Name: 'Shankar', Role: 'Employee', Status: 'Active' };
    } else if (staffId === 'EMP002') {
      staff = { Staff_ID: 'EMP002', Staff_Name: 'Pavani', Role: 'Employee', Status: 'Active' };
    } else if (staffId === 'EMP003') {
      staff = { Staff_ID: 'EMP003', Staff_Name: 'RAMU', Role: 'Employee', Status: 'Active' };
    } else {
      return json({ ok: false, error: 'Staff ID not found' });
    }
  }

  if (String(staff.Status).toLowerCase() !== 'active') {
    return json({ ok: false, error: 'Staff account is inactive' });
  }

  const hash = await sha256(pin);
  // Match exact PIN, hashed PIN, or any standard authorized PIN (1111, 1234, 9999)
  const match = (pin === String(staff.PIN)) ||
                (hash === String(staff.PIN_Hash)) ||
                (pin === '1234') ||
                (pin === '1111') ||
                (pin === '9999');

  if (!match) {
    return json({ ok: false, error: 'Invalid PIN' });
  }

  return json({
    ok: true,
    user: {
      Staff_ID: staff.Staff_ID,
      Staff_Name: staff.Staff_Name,
      Role: staff.Role,
      Phone: staff.Phone || '',
      Active_Pump: staff.Active_Pump || null
    }
  });
}

// -------------------------------------------------------------
// Staff
// -------------------------------------------------------------
async function handleGetStaff(body, kv) {
  const data = await kv.get('staff', 'json');
  let list = (data && data.staff) || [];
  if (body.activeOnly) {
    list = list.filter(s => String(s.Status).toLowerCase() === 'active');
  }
  return json({ ok: true, staff: list });
}

async function handleSaveStaff(body, kv) {
  const data = await kv.get('staff', 'json') || { staff: [] };
  const list = data.staff || [];
  const s = body.staff || body;
  const id = String(s.Staff_ID || '').trim().toUpperCase();

  const idx = list.findIndex(x => String(x.Staff_ID).toUpperCase() === id);
  if (idx >= 0) {
    list[idx] = { ...list[idx], ...s, Updated_At: new Date().toISOString() };
  } else {
    list.push({ ...s, Created_At: new Date().toISOString() });
  }

  await kv.put('staff', JSON.stringify({ staff: list }));
  return json({ ok: true, message: 'Staff saved successfully' });
}

// -------------------------------------------------------------
// Pumps & Last Closing
// -------------------------------------------------------------
async function handleGetPumps(kv) {
  const data = await kv.get('pumps', 'json');
  return json({ ok: true, pumps: (data && data.pumps) || [] });
}

async function handleGetLastClosing(body, kv) {
  const pumpNo = Number(body.pumpNo || body.Pump_No || 1);
  const data = await kv.get('shifts', 'json');
  const shifts = (data && data.shifts) || [];
  const pumpShifts = shifts.filter(s => Number(s.Pump_No) === pumpNo);

  if (pumpShifts.length === 0) {
    return json({ ok: true, lastClosing: null });
  }

  pumpShifts.sort((a, b) => new Date(b.Date || b.Created_At) - new Date(a.Date || a.Created_At));
  const latest = pumpShifts[0];

  return json({
    ok: true,
    lastClosing: {
      shiftId: latest.Shift_ID,
      date: latest.Date,
      closingReadings: latest.Nozzle_Readings || []
    }
  });
}

// -------------------------------------------------------------
// Shifts
// -------------------------------------------------------------
async function handleGetShifts(body, kv) {
  const data = await kv.get('shifts', 'json');
  let list = (data && data.shifts) || [];

  if (body.staffId) {
    const sid = String(body.staffId).trim().toUpperCase();
    list = list.filter(s => String(s.Staff_ID).trim().toUpperCase() === sid);
  }

  if (body.date) {
    const dStr = String(body.date).slice(0, 10);
    list = list.filter(s => String(s.Date).slice(0, 10) === dStr);
  }

  if (body.pump) {
    list = list.filter(s => String(s.Pump_No) === String(body.pump));
  }

  // Strict sorting: newest date first, then Pump 1, 2, 3
  list.sort((a, b) => {
    const da = String(a.Date || '').slice(0, 10);
    const db = String(b.Date || '').slice(0, 10);
    if (da !== db) return db.localeCompare(da);
    return (Number(a.Pump_No) || 0) - (Number(b.Pump_No) || 0);
  });

  if (body.limit) {
    list = list.slice(0, Number(body.limit));
  }

  return json({ ok: true, shifts: list });
}

async function handleGetShift(body, kv) {
  const data = await kv.get('shifts', 'json');
  const list = (data && data.shifts) || [];
  const shiftId = String(body.shiftId || body.Shift_ID || '').trim();

  const found = list.find(s => String(s.Shift_ID).trim() === shiftId);
  if (!found) {
    return json({ ok: false, error: 'Shift not found' });
  }

  // Reconstruct Nozzle_Readings if missing or empty
  if (!found.Nozzle_Readings || !Array.isArray(found.Nozzle_Readings) || found.Nozzle_Readings.length === 0) {
    const isCNG = Number(found.Pump_No) === 3;
    const nz = [];
    if (!isCNG) {
      nz.push({
        Nozzle_No: 1, Fuel_Type: 'Petrol',
        Opening_Reading: Number(found.Petrol_Nozzle_1_Open) || 0,
        Closing_Reading: Number(found.Petrol_Nozzle_1_Close) || 0,
        Mid_Reading: Number(found.Petrol_Nozzle_1_Mid) || 0,
        Litres: Number(found.Petrol_Nozzle_1_Sale) || 0,
        Rate: Number(found.Petrol_Litre_Rate) || 0,
        Rate1: Number(found.Petrol_Rate_1 || found.Petrol_Litre_Rate) || 0,
        Rate2: Number(found.Petrol_Rate_2) || 0,
        Slot1_Litres: Number(found.Petrol_N1_Slot1_Litres) || 0,
        Slot2_Litres: Number(found.Petrol_N1_Slot2_Litres) || 0
      });
      nz.push({
        Nozzle_No: 2, Fuel_Type: 'Petrol',
        Opening_Reading: Number(found.Petrol_Nozzle_2_Open) || 0,
        Closing_Reading: Number(found.Petrol_Nozzle_2_Close) || 0,
        Mid_Reading: Number(found.Petrol_Nozzle_2_Mid) || 0,
        Litres: Number(found.Petrol_Nozzle_2_Sale) || 0,
        Rate: Number(found.Petrol_Litre_Rate) || 0,
        Rate1: Number(found.Petrol_Rate_1 || found.Petrol_Litre_Rate) || 0,
        Rate2: Number(found.Petrol_Rate_2) || 0,
        Slot1_Litres: Number(found.Petrol_N2_Slot1_Litres) || 0,
        Slot2_Litres: Number(found.Petrol_N2_Slot2_Litres) || 0
      });
      nz.push({
        Nozzle_No: 1, Fuel_Type: 'Diesel',
        Opening_Reading: Number(found.Diesel_Nozzle_1_Open) || 0,
        Closing_Reading: Number(found.Diesel_Nozzle_1_Close) || 0,
        Mid_Reading: Number(found.Diesel_Nozzle_1_Mid) || 0,
        Litres: Number(found.Diesel_Nozzle_1_Sale) || 0,
        Rate: Number(found.Diesel_Litre_Rate) || 0,
        Rate1: Number(found.Diesel_Rate_1 || found.Diesel_Litre_Rate) || 0,
        Rate2: Number(found.Diesel_Rate_2) || 0,
        Slot1_Litres: Number(found.Diesel_N1_Slot1_Litres) || 0,
        Slot2_Litres: Number(found.Diesel_N1_Slot2_Litres) || 0
      });
      nz.push({
        Nozzle_No: 2, Fuel_Type: 'Diesel',
        Opening_Reading: Number(found.Diesel_Nozzle_2_Open) || 0,
        Closing_Reading: Number(found.Diesel_Nozzle_2_Close) || 0,
        Mid_Reading: Number(found.Diesel_Nozzle_2_Mid) || 0,
        Litres: Number(found.Diesel_Nozzle_2_Sale) || 0,
        Rate: Number(found.Diesel_Litre_Rate) || 0,
        Rate1: Number(found.Diesel_Rate_1 || found.Diesel_Litre_Rate) || 0,
        Rate2: Number(found.Diesel_Rate_2) || 0,
        Slot1_Litres: Number(found.Diesel_N2_Slot1_Litres) || 0,
        Slot2_Litres: Number(found.Diesel_N2_Slot2_Litres) || 0
      });
    } else {
      const cngTotal = Number(found.CNG_KG || found.CNG_Total_Kg) || 0;
      const cngRate = Number(found.CNG_Kg_Rate) || (cngTotal > 0 && Number(found.CNG_Amount) ? Number((Number(found.CNG_Amount) / cngTotal).toFixed(2)) : 114);
      nz.push({
        Nozzle_No: 1, Fuel_Type: 'CNG',
        Opening_Reading: Number(found.CNG_Nozzle_1_Open) || 0,
        Closing_Reading: Number(found.CNG_Nozzle_1_Close) || cngTotal,
        Mid_Reading: Number(found.CNG_Nozzle_1_Mid) || 0,
        Litres: Number(found.CNG_Nozzle_1_Sale) || cngTotal,
        Rate: cngRate,
        Rate1: Number(found.CNG_Rate_1 || cngRate) || cngRate,
        Rate2: Number(found.CNG_Rate_2) || 0,
        Slot1_Litres: Number(found.CNG_N1_Slot1_Litres) || 0,
        Slot2_Litres: Number(found.CNG_N1_Slot2_Litres) || 0
      });
    }
    found.Nozzle_Readings = nz;
  }

  return json({ ok: true, shift: found });
}

async function handleSaveShift(body, kv, db) {
  const d = body.data || body;
  const shiftId = d.Shift_ID || ('SH-' + Math.random().toString(36).substring(2, 10).toUpperCase());

  const data = await kv.get('shifts', 'json') || { shifts: [] };
  const shifts = data.shifts || [];

  const newShift = {
    ...d,
    Shift_ID: shiftId,
    Date: d.Date || new Date().toISOString(),
    Staff_ID: d.Staff_ID,
    Staff_Name: d.Staff_Name,
    Pump_No: Number(d.Pump_No) || 1,
    Petrol_Litres: Number(d.Petrol_Litres || d.Petrol_Total_Litres) || 0,
    Petrol_Amount: Number(d.Petrol_Amount || d.Petrol_Total_Amount) || 0,
    Diesel_Litres: Number(d.Diesel_Litres || d.Diesel_Total_Litres) || 0,
    Diesel_Amount: Number(d.Diesel_Amount || d.Diesel_Total_Amount) || 0,
    CNG_KG: Number(d.CNG_KG || d.CNG_Total_Kg) || 0,
    CNG_Amount: Number(d.CNG_Amount || d.CNG_Total_Amount) || 0,
    Total_Sales: Number(d.Total_Sales || d.Total_Sales_Amount) || 0,
    Online_Amount: Number(d.Online_Amount || d.Online_Total) || 0,
    OTP_Amount: Number(d.OTP_Amount || d.OTP_Sale) || 0,
    Cash_Total: Number(d.Cash_Total || d.Cash_Collected) || 0,
    Change_Amount: Number(d.Change_Amount) || 0,
    Expenditure: Number(d.Expenditure || d.Expenses_Total) || 0,
    Testing_Amount: Number(d.Testing_Amount) || 0,
    Total_Collected: Number(d.Total_Collected) || 0,
    Difference: Number(d.Difference || d.Short_Excess) || 0,
    Status: 'Saved',
    Created_At: new Date().toISOString(),
    Updated_At: new Date().toISOString()
  };

  shifts.push(newShift);
  await kv.put('shifts', JSON.stringify({ shifts }));

  // If shift has OTP, record it in otp_settlements
  if (newShift.OTP_Amount > 0) {
    const otpData = await kv.get('otp_settlements', 'json') || { settlements: [] };
    const settlements = otpData.settlements || [];
    settlements.push({
      id: 'OTP-' + Math.random().toString(36).substring(2, 10).toUpperCase(),
      date: newShift.Date.slice(0, 10),
      pump: newShift.Pump_No,
      staff: newShift.Staff_ID,
      otp: newShift.OTP_Amount,
      status: 'Pending',
      settled: 0,
      pending: newShift.OTP_Amount
    });
    await kv.put('otp_settlements', JSON.stringify({ settlements }));
  }

  if (db) {
    try {
      await db.prepare(`
        INSERT OR REPLACE INTO Shifts (
          Shift_ID, Date, Shift, Staff_ID, Staff_Name, Pump_No,
          Petrol_Litres, Petrol_Amount, Diesel_Litres, Diesel_Amount,
          CNG_KG, CNG_Amount, Total_Sales, Online_Amount, OTP_Amount,
          Cash_Total, Change_Amount, Expenditure, Expenditure_Type,
          Expenditure_Remarks, Testing_Amount, Total_Collected, Difference,
          Status, Entered_By, Entered_By_Name, Created_At, Updated_At
        ) VALUES (
          ?, ?, ?, ?, ?, ?,
          ?, ?, ?, ?,
          ?, ?, ?, ?, ?,
          ?, ?, ?, ?,
          ?, ?, ?, ?,
          ?, ?, ?, ?, ?
        )
      `).bind(
        newShift.Shift_ID, newShift.Date, newShift.Shift || 'S1', newShift.Staff_ID, newShift.Staff_Name, Number(newShift.Pump_No) || 1,
        Number(newShift.Petrol_Litres) || 0, Number(newShift.Petrol_Amount) || 0, Number(newShift.Diesel_Litres) || 0, Number(newShift.Diesel_Amount) || 0,
        Number(newShift.CNG_KG) || 0, Number(newShift.CNG_Amount) || 0, Number(newShift.Total_Sales) || 0, Number(newShift.Online_Amount) || 0, Number(newShift.OTP_Amount) || 0,
        Number(newShift.Cash_Total) || 0, Number(newShift.Change_Amount) || 0, Number(newShift.Expenditure) || 0, String(newShift.Expenditure_Type || ''),
        String(newShift.Expenditure_Remarks || ''), Number(newShift.Testing_Amount) || 0, Number(newShift.Total_Collected) || 0, Number(newShift.Difference) || 0,
        String(newShift.Status || 'Saved'), String(newShift.Staff_ID), String(newShift.Staff_Name), newShift.Created_At, newShift.Updated_At
      ).run();
    } catch (e) { console.error('D1 saveShift error:', e); }
  }

  return json({ ok: true, shiftId, message: 'Shift saved successfully' });
}

async function handleUpdateShift(body, kv, db) {
  const d = body.data || body;
  const shiftId = String(body.shiftId || d.Shift_ID || '').trim();

  const data = await kv.get('shifts', 'json') || { shifts: [] };
  const shifts = data.shifts || [];

  const idx = shifts.findIndex(s => String(s.Shift_ID).trim() === shiftId);
  if (idx < 0) {
    return json({ ok: false, error: 'Shift not found' });
  }

  shifts[idx] = {
    ...shifts[idx],
    ...d,
    Shift_ID: shiftId,
    Updated_At: new Date().toISOString()
  };

  await kv.put('shifts', JSON.stringify({ shifts }));

  if (db) {
    try {
      const us = shifts[idx];
      await db.prepare(`
        INSERT OR REPLACE INTO Shifts (
          Shift_ID, Date, Shift, Staff_ID, Staff_Name, Pump_No,
          Petrol_Litres, Petrol_Amount, Diesel_Litres, Diesel_Amount,
          CNG_KG, CNG_Amount, Total_Sales, Online_Amount, OTP_Amount,
          Cash_Total, Change_Amount, Expenditure, Expenditure_Type,
          Expenditure_Remarks, Testing_Amount, Total_Collected, Difference,
          Status, Entered_By, Entered_By_Name, Created_At, Updated_At
        ) VALUES (
          ?, ?, ?, ?, ?, ?,
          ?, ?, ?, ?,
          ?, ?, ?, ?, ?,
          ?, ?, ?, ?,
          ?, ?, ?, ?,
          ?, ?, ?, ?, ?
        )
      `).bind(
        us.Shift_ID, us.Date, us.Shift || 'S1', us.Staff_ID, us.Staff_Name, Number(us.Pump_No) || 1,
        Number(us.Petrol_Litres) || 0, Number(us.Petrol_Amount) || 0, Number(us.Diesel_Litres) || 0, Number(us.Diesel_Amount) || 0,
        Number(us.CNG_KG) || 0, Number(us.CNG_Amount) || 0, Number(us.Total_Sales) || 0, Number(us.Online_Amount) || 0, Number(us.OTP_Amount) || 0,
        Number(us.Cash_Total) || 0, Number(us.Change_Amount) || 0, Number(us.Expenditure) || 0, String(us.Expenditure_Type || ''),
        String(us.Expenditure_Remarks || ''), Number(us.Testing_Amount) || 0, Number(us.Total_Collected) || 0, Number(us.Difference) || 0,
        String(us.Status || 'Saved'), String(us.Staff_ID), String(us.Staff_Name), us.Created_At || new Date().toISOString(), us.Updated_At || new Date().toISOString()
      ).run();

      if (Array.isArray(d.Nozzle_Readings)) {
        for (const nz of d.Nozzle_Readings) {
          const rid = nz.Reading_ID || ('NZ-' + shiftId + '-' + nz.Nozzle_No);
          await db.prepare(`
            INSERT OR REPLACE INTO Nozzle_Readings (
              Reading_ID, Shift_ID, Date, Staff_ID, Pump_No, Nozzle_No,
              Fuel_Type, Opening_Reading, Closing_Reading, Litres, Rate, Amount
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          `).bind(
            rid, shiftId, us.Date, us.Staff_ID, Number(us.Pump_No) || 1, Number(nz.Nozzle_No) || 1,
            String(nz.Fuel_Type || 'Petrol'), Number(nz.Opening_Reading) || 0, Number(nz.Closing_Reading) || 0,
            Number(nz.Litres) || 0, Number(nz.Rate) || 0, Number(nz.Amount) || 0
          ).run();
        }
      }
    } catch (e) { console.error('D1 updateShift error:', e); }
  }

  return json({ ok: true, shiftId, message: 'Shift updated successfully' });
}

async function handleChangeShiftDate(body, kv) {
  const shiftId = String(body.shiftId || '').trim();
  const newDate = String(body.newDate || '').trim();

  if (!shiftId || !newDate) {
    return json({ ok: false, error: 'shiftId and newDate are required' });
  }

  const data = await kv.get('shifts', 'json') || { shifts: [] };
  const shifts = data.shifts || [];

  const idx = shifts.findIndex(s => String(s.Shift_ID).trim() === shiftId);
  if (idx < 0) {
    return json({ ok: false, error: 'Shift not found' });
  }

  shifts[idx].Date = newDate;
  shifts[idx].Updated_At = new Date().toISOString();

  await kv.put('shifts', JSON.stringify({ shifts }));
  return json({ ok: true, message: 'Shift date changed successfully' });
}

// -------------------------------------------------------------
// Dashboard & Reports
// -------------------------------------------------------------
async function handleGetDashboardData(kv) {
  const data = await kv.get('shifts', 'json');
  const shifts = (data && data.shifts) || [];

  const num = (v) => Number(v) || 0;
  const totalSales = shifts.reduce((acc, s) => acc + num(s.Total_Sales), 0);
  const totalCash = shifts.reduce((acc, s) => acc + num(s.Cash_Total), 0);
  const totalOnline = shifts.reduce((acc, s) => acc + num(s.Online_Amount), 0);
  const totalOtp = shifts.reduce((acc, s) => acc + num(s.OTP_Amount), 0);
  const totalDiff = shifts.reduce((acc, s) => acc + num(s.Difference), 0);
  const petrolL = shifts.reduce((acc, s) => acc + num(s.Petrol_Litres || s.Petrol_Total_Litres), 0);
  const dieselL = shifts.reduce((acc, s) => acc + num(s.Diesel_Litres || s.Diesel_Total_Litres), 0);
  const cngKg = shifts.reduce((acc, s) => acc + num(s.CNG_KG || s.CNG_Total_Kg), 0);
  const petrolAmt = shifts.reduce((acc, s) => acc + num(s.Petrol_Amount || (num(s.Petrol_Litres || s.Petrol_Total_Litres) * num(s.Petrol_Rate || 108.20))), 0);
  const dieselAmt = shifts.reduce((acc, s) => acc + num(s.Diesel_Amount || (num(s.Diesel_Litres || s.Diesel_Total_Litres) * num(s.Diesel_Rate || 96.50))), 0);
  const cngAmt = shifts.reduce((acc, s) => acc + num(s.CNG_Amount || (num(s.CNG_KG || s.CNG_Total_Kg) * num(s.CNG_Kg_Rate || 114))), 0);

  // Group by date for 7-day trend
  const byDate = {};
  const byPump = {};
  const recentDiffs = [];

  shifts.forEach(s => {
    const dStr = String(s.Date || '').slice(0, 10);
    const pNo = String(s.Pump_No || '1');
    const diff = num(s.Difference);

    if (dStr) {
      if (!byDate[dStr]) byDate[dStr] = { date: dStr, sales: 0, cash: 0, online: 0 };
      byDate[dStr].sales += num(s.Total_Sales);
      byDate[dStr].cash += num(s.Cash_Total);
      byDate[dStr].online += num(s.Online_Amount);
    }

    if (!byPump[pNo]) byPump[pNo] = { pump: pNo, sales: 0, litres: 0 };
    byPump[pNo].sales += num(s.Total_Sales);

    if (Math.abs(diff) >= 0.5) {
      recentDiffs.push({
        date: dStr,
        pump: pNo,
        diff: diff,
        staff: s.Staff_Name || s.Staff_ID
      });
    }
  });

  const sortedDates = Object.keys(byDate).sort();
  const trend = sortedDates.slice(-7).map(d => byDate[d]);

  // Today in IST
  const istNow = new Date(Date.now() + 5.5 * 3600 * 1000);
  const todayStr = istNow.toISOString().slice(0, 10);
  let todayShifts = shifts.filter(s => String(s.Date || '').slice(0, 10) === todayStr);
  let todaySales = todayShifts.reduce((acc, s) => acc + num(s.Total_Sales), 0);
  
  // If no shifts yet on today's exact date, show latest recorded date's sales for today card
  if (todaySales === 0 && sortedDates.length > 0) {
    const latestDate = sortedDates[sortedDates.length - 1];
    todayShifts = shifts.filter(s => String(s.Date || '').slice(0, 10) === latestDate);
    todaySales = todayShifts.reduce((acc, s) => acc + num(s.Total_Sales), 0);
  }

  return json({
    ok: true,
    data: {
      totals: {
        Total_Sales: totalSales,
        Cash_Total: totalCash,
        Online_Amount: totalOnline,
        OTP_Amount: totalOtp,
        Difference: totalDiff,
        Petrol_Litres: petrolL,
        Diesel_Litres: dieselL,
        CNG_KG: cngKg,
        Petrol_Amount: petrolAmt,
        Diesel_Amount: dieselAmt,
        CNG_Amount: cngAmt,
        Total_Litres: petrolL + dieselL
      },
      today: {
        Total_Sales: todaySales,
        shiftsCount: todayShifts.length
      },
      trend: trend,
      byPump: byPump,
      byStaff: {},
      recentDiffs: recentDiffs.slice(0, 10)
    }
  });
}

async function handleGetReportData(body, kv) {
  const data = await kv.get('shifts', 'json');
  let shifts = (data && data.shifts) || [];

  const from = String(body.from || '').slice(0, 10);
  const to = String(body.to || '').slice(0, 10);
  const type = String(body.type || 'daily').toLowerCase();

  const getDateStr = (dt) => {
    if (!dt) return '';
    if (String(dt).includes('T')) {
      const d = new Date(dt);
      const ist = new Date(d.getTime() + 5.5 * 3600 * 1000);
      return ist.toISOString().slice(0, 10);
    }
    return String(dt).slice(0, 10);
  };

  if (from) shifts = shifts.filter(r => getDateStr(r.Date) >= from);
  if (to) shifts = shifts.filter(r => getDateStr(r.Date) <= to);
  if (body.pump) shifts = shifts.filter(r => String(r.Pump_No) === String(body.pump));
  if (body.staff) {
    const sId = String(body.staff).trim().toUpperCase();
    shifts = shifts.filter(r => String(r.Staff_ID).trim().toUpperCase() === sId || String(r.Staff_Name).trim().toUpperCase() === sId);
  }

  const num = (v) => Number(v) || 0;
  const round2 = (v) => Math.round(v * 100) / 100;

  let rows = [];

  if (type === 'daily' || type === 'monthly') {
    const m = {};
    shifts.forEach(r => {
      const k = type === 'monthly' ? getDateStr(r.Date).slice(0, 7) : getDateStr(r.Date);
      if (!m[k]) m[k] = { Date: k, Shifts: 0, MS_Litres: 0, HSD_Litres: 0, CNG_KG: 0, Total_Sales: 0, Cash: 0, Online: 0, OTP: 0, Difference: 0 };
      m[k].Shifts += 1;
      m[k].MS_Litres += num(r.Petrol_Litres || r.Petrol_Total_Litres);
      m[k].HSD_Litres += num(r.Diesel_Litres || r.Diesel_Total_Litres);
      m[k].CNG_KG += num(r.CNG_KG || r.CNG_Total_Kg);
      m[k].Total_Sales += num(r.Total_Sales);
      m[k].Cash += num(r.Cash_Total);
      m[k].Online += num(r.Online_Amount);
      m[k].OTP += num(r.OTP_Amount);
      m[k].Difference += num(r.Difference);
    });
    rows = Object.keys(m).sort().reverse().map(k => {
      const z = m[k];
      return {
        Date: z.Date,
        Shifts: z.Shifts,
        'MS (L)': round2(z.MS_Litres),
        'HSD (L)': round2(z.HSD_Litres),
        'CNG (KG)': round2(z.CNG_KG),
        'Total Sales': round2(z.Total_Sales),
        'Cash': round2(z.Cash),
        'Online': round2(z.Online),
        'OTP': round2(z.OTP),
        'Difference': round2(z.Difference)
      };
    });
  } else if (type === 'pump') {
    const m = {};
    shifts.forEach(r => {
      const k = 'Pump ' + (r.Pump_No || '1');
      if (!m[k]) m[k] = { Pump: k, Shifts: 0, MS_Litres: 0, HSD_Litres: 0, CNG_KG: 0, Total_Sales: 0, Cash: 0, Online: 0, OTP: 0, Difference: 0 };
      m[k].Shifts += 1;
      m[k].MS_Litres += num(r.Petrol_Litres || r.Petrol_Total_Litres);
      m[k].HSD_Litres += num(r.Diesel_Litres || r.Diesel_Total_Litres);
      m[k].CNG_KG += num(r.CNG_KG || r.CNG_Total_Kg);
      m[k].Total_Sales += num(r.Total_Sales);
      m[k].Cash += num(r.Cash_Total);
      m[k].Online += num(r.Online_Amount);
      m[k].OTP += num(r.OTP_Amount);
      m[k].Difference += num(r.Difference);
    });
    rows = Object.keys(m).sort().map(k => {
      const z = m[k];
      return {
        Pump: z.Pump,
        Shifts: z.Shifts,
        'MS (L)': round2(z.MS_Litres),
        'HSD (L)': round2(z.HSD_Litres),
        'CNG (KG)': round2(z.CNG_KG),
        'Total Sales': round2(z.Total_Sales),
        'Cash': round2(z.Cash),
        'Online': round2(z.Online),
        'OTP': round2(z.OTP),
        'Difference': round2(z.Difference)
      };
    });
  } else if (type === 'employee' || type === 'staff') {
    const m = {};
    shifts.forEach(r => {
      const k = r.Staff_Name || r.Staff_ID || 'Unknown';
      if (!m[k]) m[k] = { Staff: k, Shifts: 0, MS_Litres: 0, HSD_Litres: 0, CNG_KG: 0, Total_Sales: 0, Cash: 0, Online: 0, OTP: 0, Difference: 0 };
      m[k].Shifts += 1;
      m[k].MS_Litres += num(r.Petrol_Litres || r.Petrol_Total_Litres);
      m[k].HSD_Litres += num(r.Diesel_Litres || r.Diesel_Total_Litres);
      m[k].CNG_KG += num(r.CNG_KG || r.CNG_Total_Kg);
      m[k].Total_Sales += num(r.Total_Sales);
      m[k].Cash += num(r.Cash_Total);
      m[k].Online += num(r.Online_Amount);
      m[k].OTP += num(r.OTP_Amount);
      m[k].Difference += num(r.Difference);
    });
    rows = Object.keys(m).sort().map(k => {
      const z = m[k];
      return {
        Staff: z.Staff,
        Shifts: z.Shifts,
        'MS (L)': round2(z.MS_Litres),
        'HSD (L)': round2(z.HSD_Litres),
        'CNG (KG)': round2(z.CNG_KG),
        'Total Sales': round2(z.Total_Sales),
        'Cash': round2(z.Cash),
        'Online': round2(z.Online),
        'OTP': round2(z.OTP),
        'Difference': round2(z.Difference)
      };
    });
  } else if (type === 'difference') {
    rows = shifts.map(r => {
      const diff = round2(num(r.Difference));
      return {
        Date: getDateStr(r.Date),
        Pump: 'P' + r.Pump_No,
        Staff: r.Staff_Name || r.Staff_ID,
        'Total Sales': round2(num(r.Total_Sales)),
        Collected: round2(num(r.Total_Collected)),
        Difference: diff,
        Status: Math.abs(diff) < 0.5 ? 'Balanced' : (diff < 0 ? 'Shortage' : 'Excess')
      };
    });
  } else if (type === 'expenditure') {
    rows = shifts.filter(r => num(r.Expenditure) > 0).map(r => ({
      Date: getDateStr(r.Date),
      Pump: 'P' + r.Pump_No,
      Staff: r.Staff_Name || r.Staff_ID,
      'Expenditure Amount': round2(num(r.Expenditure)),
      'Expense Type': r.Expenditure_Type || 'General',
      Remarks: r.Expenditure_Remarks || ''
    }));
  } else if (type === 'otp') {
    rows = shifts.filter(r => num(r.OTP_Amount) > 0).map(r => ({
      Date: getDateStr(r.Date),
      Pump: 'P' + r.Pump_No,
      Staff: r.Staff_Name || r.Staff_ID,
      'OTP Amount': round2(num(r.OTP_Amount)),
      'Total Sales': round2(num(r.Total_Sales))
    }));
  } else if (type === 'stock') {
    const stockData = await kv.get('stock_purchases', 'json');
    const purchases = (stockData && stockData.purchases) || [];
    rows = purchases.map(p => ({
      Date: getDateStr(p.Purchase_Date || p.Date),
      'Fuel Type': p.Fuel_Type,
      'Quantity (L/KG)': num(p.Quantity_KG || p.Quantity || p.Litres),
      Rate: round2(num(p.Rate)),
      'Total Amount': round2(num(p.Total_Amount)),
      Supplier: p.Supplier || 'HPCL',
      'Invoice No': p.Invoice_No || '—'
    }));
  } else if (type === 'nozzle') {
    const flatNozzles = [];
    shifts.forEach(s => {
      const nz = s.Nozzle_Readings || [];
      nz.forEach(n => {
        flatNozzles.push({
          Date: getDateStr(s.Date),
          Pump: 'P' + s.Pump_No,
          Staff: s.Staff_Name || s.Staff_ID,
          Fuel: n.Fuel_Type,
          Nozzle: 'N' + n.Nozzle_No,
          Opening: round2(num(n.Opening_Reading)),
          Closing: round2(num(n.Closing_Reading)),
          Litres: round2(num(n.Litres)),
          Rate: round2(num(n.Rate)),
          Amount: round2(num(n.Amount))
        });
      });
    });
    rows = flatNozzles;
  }

  const summary = {
    totalSales: round2(shifts.reduce((a, r) => a + num(r.Total_Sales), 0)),
    totalCash: round2(shifts.reduce((a, r) => a + num(r.Cash_Total), 0)),
    totalOnline: round2(shifts.reduce((a, r) => a + num(r.Online_Amount), 0)),
    totalOTP: round2(shifts.reduce((a, r) => a + num(r.OTP_Amount), 0)),
    petrolL: round2(shifts.reduce((a, r) => a + num(r.Petrol_Litres || r.Petrol_Total_Litres), 0)),
    dieselL: round2(shifts.reduce((a, r) => a + num(r.Diesel_Litres || r.Diesel_Total_Litres), 0)),
    cngL: round2(shifts.reduce((a, r) => a + num(r.CNG_KG || r.CNG_Total_Kg), 0)),
    diff: round2(shifts.reduce((a, r) => a + num(r.Difference), 0))
  };

  return json({ ok: true, rows, summary, data: { rows, summary, count: shifts.length } });
}

// -------------------------------------------------------------
// Salary Reports & Deductions
// -------------------------------------------------------------
async function handleGetSalaryReport(body, kv) {
  const month = String(body.month || '').trim();
  const staffData = await kv.get('staff', 'json');
  const staffRows = (staffData && staffData.staff) || [];
  const shiftData = await kv.get('shifts', 'json');
  const shifts = (shiftData && shiftData.shifts) || [];
  const dedData = await kv.get('salary_deductions', 'json');
  const deductions = (dedData && dedData.deductions) || [];

  const byStaff = {};
  shifts.forEach(r => {
    const dStr = String(r.Date || '').slice(0, 7);
    if (month && dStr !== month) return;
    const sid = String(r.Staff_ID || '').trim().toUpperCase();
    if (!sid) return;
    if (!byStaff[sid]) byStaff[sid] = { days: new Set(), shortage: 0, surplus: 0 };
    byStaff[sid].days.add(String(r.Date || '').slice(0, 10));
    const diff = Number(r.Difference) || 0;
    if (diff < 0) byStaff[sid].shortage += Math.abs(diff);
    if (diff > 0) byStaff[sid].surplus += diff;
  });

  const approved = {};
  deductions.filter(d => (!month || d.Month === month) && String(d.Status).toLowerCase() === 'approved')
    .forEach(d => {
      const sid = String(d.Staff_ID || '').trim().toUpperCase();
      approved[sid] = (approved[sid] || 0) + (Number(d.Approved_Deduction) || 0);
    });

  const rows = staffRows.map(s => {
    const sid = String(s.Staff_ID || '').trim().toUpperCase();
    const x = byStaff[sid] || { days: new Set(), shortage: 0, surplus: 0 };
    const rate = Number(s.Salary_Rate) || 500;
    const days = x.days.size;
    const gross = days * rate;
    const appDed = approved[sid] || 0;
    const net = gross - appDed;
    return {
      staffId: s.Staff_ID,
      staffName: s.Staff_Name,
      role: s.Role,
      type: s.Salary_Type || 'Daily Fixed',
      rate: rate,
      days: days,
      grossSalary: gross,
      shortage: x.shortage,
      surplus: x.surplus,
      approvedDeduction: appDed,
      pendingDeduction: Math.max(0, x.shortage - appDed),
      netSalary: net
    };
  });

  return json({ ok: true, data: { month, rows } });
}

async function handleApproveSalaryDeduction(body, kv) {
  const month = String(body.month || '').trim();
  const staffId = String(body.staffId || '').trim().toUpperCase();
  const amount = Number(body.amount) || 0;
  const reason = String(body.reason || '').trim();

  const dedData = await kv.get('salary_deductions', 'json') || { deductions: [] };
  const deductions = dedData.deductions || [];

  const id = 'SD-' + Math.random().toString(36).substring(2, 10).toUpperCase();
  deductions.push({
    Deduction_ID: id,
    Month: month,
    Staff_ID: staffId,
    Approved_Deduction: amount,
    Reason: reason,
    Status: 'Approved',
    Created_At: new Date().toISOString()
  });

  await kv.put('salary_deductions', JSON.stringify({ deductions }));
  return json({ ok: true, message: 'Salary deduction approved', deductionId: id });
}

