async function handleSaveStockPurchase(body, kv) {
  const d = body.data || body;
  const qty = Number(d.Quantity_KG) || 0;
  const rate = Number(d.Rate) || 0;
  const amount = Number(d.Total_Amount) || (qty * rate);

  const data = await kv.get('stock_purchases', 'json') || { purchases: [] };
  const purchases = data.purchases || [];

  const id = 'PUR-' + Math.random().toString(36).substring(2, 10).toUpperCase();
  purchases.push({
    Purchase_ID: id,
    Purchase_Date: d.Purchase_Date,
    Fuel_Type: d.Fuel_Type,
    Quantity_KG: qty,
    Rate: rate,
    Total_Amount: amount,
    Supplier: d.Supplier || '',
    Invoice_No: d.Invoice_No || '',
    Payment_Type: d.Payment_Type || '',
    Remarks: d.Remarks || '',
    Created_At: new Date().toISOString()
  });

  await kv.put('stock_purchases', JSON.stringify({ purchases }));
  return json({ ok: true, purchaseId: id, message: 'Stock purchase saved successfully' });
}

