async function handleGetOTPPending(kv) {
  const data = await kv.get('otp_settlements', 'json');
  const rows = (data && data.settlements) || [];
  return json({
    ok: true,
    rows: rows.filter(r => String(r.status).toLowerCase() !== 'settled')
  });
}

async function handleSettleOTP(body, kv) {
  const id = String(body.id || '');
  const amount = Number(body.amount) || 0;

  const data = await kv.get('otp_settlements', 'json') || { settlements: [] };
  const settlements = data.settlements || [];

  const idx = settlements.findIndex(r => String(r.id) === id);
  if (idx < 0) {
    return json({ ok: false, error: 'OTP settlement not found' });
  }

  const old = settlements[idx];
  const pending = Math.max(0, (Number(old.otp) || 0) - amount);
  settlements[idx].settled = amount;
  settlements[idx].pending = pending;
  settlements[idx].status = pending <= 0 ? 'Settled' : 'Pending';

  await kv.put('otp_settlements', JSON.stringify({ settlements }));
  return json({ ok: true, status: settlements[idx].status, pending });
}

// -------------------------------------------------------------
// DSR (Daily Stock Register) & Settings
// -------------------------------------------------------------
async function handleGetDSRRegister(body, kv) {
  const fuel = String(body.fuel || 'Petrol');
  let month = String(body.month || '').slice(0, 7);
  if (!month) {
    const istNow = new Date(Date.now() + 5.5 * 3600 * 1000);
    month = istNow.toISOString().slice(0, 7);
  }

  const shiftsData = await kv.get('shifts', 'json');
  const shifts = (shiftsData && shiftsData.shifts) || [];
  const stockData = await kv.get('stock_purchases', 'json');
  const purchases = (stockData && stockData.purchases) || [];
  const dipData = await kv.get('dsr_dip', 'json');
  const dips = (dipData && dipData.dips) || [];
  const openData = await kv.get('dsr_opening', 'json');
  const openings = (openData && openData.openings) || [];
  const settingsData = await kv.get('settings', 'json');
  const settings = (settingsData && settingsData.settings) || {};

  const num = (v) => Number(v) || 0;
  const isCNG = fuel === 'CNG';
  const unit = isCNG ? 'KG' : 'Litres';
  const defaultPumpTest = isCNG ? 0 : 20;
  const tankCapacity = isCNG ? (num(settings.cngCapacity) || 5000) : (num(settings[`${fuel.toLowerCase()}Capacity`]) || 20000);

  // Determine monthStart and monthEnd
  const [yr, mo] = month.split('-').map(Number);
  const daysInMonth = new Date(yr, mo, 0).getDate();
  const monthStart = `${month}-01`;
  const monthEnd = `${month}-${String(daysInMonth).padStart(2, '0')}`;

  // Find opening for this month
  const openRecord = openings.find(o => String(o.Date).startsWith(month) && String(o.Fuel_Type).toLowerCase() === fuel.toLowerCase())
    || openings.find(o => String(o.Fuel_Type).toLowerCase() === fuel.toLowerCase());
  const openingForMonth = openRecord ? num(openRecord.Opening_Stock) : (fuel === 'Petrol' ? 7431 : (fuel === 'Diesel' ? 10220 : 5000));

  // Map meter sales by IST date (YYYY-MM-DD)
  const salesByDate = {};
  const salesField = fuel === 'Petrol' ? 'Petrol_Litres' : (fuel === 'Diesel' ? 'Diesel_Litres' : 'CNG_KG');
  shifts.forEach(s => {
    let dStr = '';
    if (String(s.Date).includes('T')) {
      const dt = new Date(s.Date);
      const istDt = new Date(dt.getTime() + 5.5 * 3600 * 1000);
      dStr = istDt.toISOString().slice(0, 10);
    } else {
      dStr = String(s.Date || '').slice(0, 10);
    }
    if (dStr.startsWith(month)) {
      const vol = num(s[salesField] || s[salesField.replace('_Litres', '_Total_Litres')]);
      salesByDate[dStr] = (salesByDate[dStr] || 0) + vol;
    }
  });

  // Map receipts by date
  const receiptByDate = {};
  purchases.forEach(p => {
    let dStr = '';
    const pDate = p.Purchase_Date || p.Date;
    if (String(pDate).includes('T')) {
      const dt = new Date(pDate);
      const istDt = new Date(dt.getTime() + 5.5 * 3600 * 1000);
      dStr = istDt.toISOString().slice(0, 10);
    } else {
      dStr = String(pDate || '').slice(0, 10);
    }
    if (dStr.startsWith(month) && String(p.Fuel_Type).toLowerCase() === fuel.toLowerCase()) {
      receiptByDate[dStr] = (receiptByDate[dStr] || 0) + num(p.Quantity_KG || p.Quantity || p.Litres);
    }
  });

  // Map dip readings by date
  const dipByDate = {};
  dips.forEach(d => {
    const dStr = String(d.Date || '').slice(0, 10);
    if (String(d.Fuel_Type).toLowerCase() === fuel.toLowerCase()) {
      dipByDate[dStr] = num(d.Closing_Dip);
    }
  });

  // Generate rows for all days in month
  let currentOpening = openingForMonth;
  let cumulativeSales = 0;
  let cumulativeVariation = 0;
  let totReceipts = 0;
  let totSalesMeter = 0;
  let totPumpTest = 0;
  let totNetSales = 0;
  let totSalesDip = 0;

  const rows = [];
  for (let day = 1; day <= daysInMonth; day++) {
    const dt = `${month}-${String(day).padStart(2, '0')}`;
    const rct = receiptByDate[dt] || 0;
    const totStock = currentOpening + rct;
    const meter = salesByDate[dt] || 0;
    const test = (meter > 0 && !isCNG) ? defaultPumpTest : 0;
    const net = Math.max(0, meter - test);
    cumulativeSales += net;

    const dip = dipByDate[dt] !== undefined ? dipByDate[dt] : null;
    let dipSales = null;
    let varDaily = null;

    if (dip !== null) {
      dipSales = Math.max(0, totStock - dip);
      varDaily = dipSales - net;
      cumulativeVariation += varDaily;
      totSalesDip += dipSales;
    }

    rows.push({
      date: dt,
      opening: Math.round(currentOpening * 100) / 100,
      receipt: rct,
      totalStock: Math.round(totStock * 100) / 100,
      salesByMeter: Math.round(meter * 100) / 100,
      pumpTest: test,
      netSales: Math.round(net * 100) / 100,
      cumulativeSales: Math.round(cumulativeSales * 100) / 100,
      salesByDip: dipSales !== null ? Math.round(dipSales * 100) / 100 : null,
      closingDip: dip,
      variationDaily: varDaily !== null ? Math.round(varDaily * 100) / 100 : null,
      variationCumulative: dip !== null ? Math.round(cumulativeVariation * 100) / 100 : null,
      remarks: ''
    });

    totReceipts += rct;
    totSalesMeter += meter;
    totPumpTest += test;
    totNetSales += net;

    // Advance to next day opening
    currentOpening = (dip !== null) ? dip : Math.max(0, totStock - net);
  }

  const summary = {
    opening: openingForMonth,
    receipt: totReceipts,
    salesMeter: Math.round(totSalesMeter * 100) / 100,
    pumpTest: totPumpTest,
    netSales: Math.round(totNetSales * 100) / 100,
    salesDip: Math.round(totSalesDip * 100) / 100,
    variation: Math.round(cumulativeVariation * 100) / 100,
    closing: Math.round(currentOpening * 100) / 100
  };

  return json({
    ok: true,
    data: {
      fuel,
      unit,
      monthStart,
      monthEnd,
      tankCapacity,
      defaultPumpTest,
      openingForMonth,
      rows,
      summary
    }
  });
}

async function handleSaveDSRDipReading(body, kv) {
  const date = String(body.date || '').slice(0, 10);
  const fuel = String(body.fuel || 'Petrol');
  const closingDip = Number(body.closingDip || body.dip) || 0;

  const data = await kv.get('dsr_dip', 'json') || { dips: [] };
  const dips = data.dips || [];
  const idx = dips.findIndex(d => String(d.Date).slice(0, 10) === date && String(d.Fuel_Type).toLowerCase() === fuel.toLowerCase());
  if (idx >= 0) {
    dips[idx].Closing_Dip = closingDip;
    dips[idx].Remarks = body.remarks || '';
    dips[idx].Updated_At = new Date().toISOString();
  } else {
    dips.push({
      Date: date,
      Fuel_Type: fuel,
      Closing_Dip: closingDip,
      Remarks: body.remarks || '',
      Created_At: new Date().toISOString()
    });
  }
  await kv.put('dsr_dip', JSON.stringify({ dips }));
  return json({ ok: true, message: 'Daily dip saved' });
}

async function handleSaveDSROpening(body, kv) {
  const date = String(body.date || '').slice(0, 10);
  const fuel = String(body.fuel || 'Petrol');
  const openingStock = Number(body.openingStock !== undefined ? body.openingStock : body.opening) || 0;

  const data = await kv.get('dsr_opening', 'json') || { openings: [] };
  const openings = data.openings || [];
  const idx = openings.findIndex(o => String(o.Date).slice(0, 7) === date.slice(0, 7) && String(o.Fuel_Type).toLowerCase() === fuel.toLowerCase());
  if (idx >= 0) {
    openings[idx].Opening_Stock = openingStock;
    openings[idx].Date = date;
    openings[idx].Updated_At = new Date().toISOString();
  } else {
    openings.push({
      Date: date,
      Fuel_Type: fuel,
      Opening_Stock: openingStock,
      Created_At: new Date().toISOString()
    });
  }
  await kv.put('dsr_opening', JSON.stringify({ openings }));
  return json({ ok: true, message: 'Opening stock saved' });
}

async function handleSaveDSRDip(body, kv) {
  const fuel = String(body.fuel || 'Petrol');
  const dip = Number(body.dip) || 20;
  const data = await kv.get('settings', 'json') || { settings: {} };
  data.settings[`${fuel.toLowerCase()}PumpTest`] = dip;
  await kv.put('settings', JSON.stringify(data));
  return json({ ok: true, message: 'Pump test setting saved' });
}

async function handleSaveSetting(body, kv) {
  const data = await kv.get('settings', 'json') || { settings: {} };
  data.settings[body.key] = body.value;
  await kv.put('settings', JSON.stringify(data));
  return json({ ok: true, message: 'Setting saved' });
}

